import {icon,mark} from './icons.js';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const S={view:'dashboard',market:'all',job:null,results:null,letter:null,dirty:false};
const labels={india_remote:'India / remote',relocation:'Relocation'};
const button=(text,action,primary=false,attrs='')=>`<button class="btn ${primary?'primary':''}" data-action="${action}" ${attrs}>${text}</button>`;
const field=(name,label,value='',type='text')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${type==='date'?'':'maxlength="2000"'}></label>`;
const area=(name,label,value='',max=6000)=>`<label class="field full">${label}<textarea name="${name}" maxlength="${max}" rows="5">${esc(value)}</textarea></label>`;
const consent=text=>`<label class="fact-choice"><input type="checkbox" name="confirmed" required> ${text}</label>`;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(S.timer);S.timer=setTimeout(()=>$('#toast').classList.remove('show'),6000)}
async function api(path,data){const r=await fetch('/api/'+path,{method:data===undefined?'GET':'POST',headers:{'X-RoleWeave-Token':$('meta[name=roleweave-session]').content,...(data===undefined?{}:{'Content-Type':'application/json'})},body:data===undefined?undefined:JSON.stringify(data)});const out=await r.json();if(!r.ok)throw Error(out.error||'Action unavailable');return out}
async function download(path){const r=await fetch('/api/'+path,{headers:{'X-RoleWeave-Token':$('meta[name=roleweave-session]').content}});if(!r.ok){const d=await r.json();throw Error(d.error)}const u=URL.createObjectURL(await r.blob()),a=document.createElement('a');a.href=u;a.download=(r.headers.get('Content-Disposition')||'').match(/filename="([^"]+)"/)?.[1]||'RoleWeave-download';a.click();setTimeout(()=>URL.revokeObjectURL(u),30000)}
function safeLink(value,text='Open employer page'){try{const u=new URL(value);if(u.protocol==='https:'&&!u.username&&!u.password)return `<a class="btn" href="${esc(u.href)}" target="_blank" rel="noopener noreferrer">${text} ${icon('external')}</a>`}catch{}return '<span class="muted">No application destination saved</span>'}
const badge=stage=>`<span class="pill">${esc(stage)}</span>`;
function modal(title,body){S.documentPreview=null;$('#modal').classList.toggle('studio-modal',title==='Build your application resume');$('#modal-content').innerHTML=`<div class="modal-head"><h2>${title}</h2>${button('×','close')}</div><div class="modal-body">${body}<p class="modal-error" role="alert"></p></div>`;$('#modal').showModal()}
function close(){if(S.modalDirty&&!confirm('Discard these unsaved changes?'))return;S.modalDirty=false;$('#modal').close()}
async function refresh(){Object.assign(S,await api('bootstrap'))}
const activeJobs=()=>S.jobs.filter(j=>(S.market==='all'||j.market===S.market)&&(!S.boardStage||j.stage===S.boardStage)&&(!S.boardDue||(j.follow_up&&j.follow_up<=localDate()&&!['closed','withdrawn'].includes(j.stage)))&&(!S.boardQuery||(j.title+' '+j.company+' '+j.note+' '+j.source_url).toLocaleLowerCase().includes(S.boardQuery.toLocaleLowerCase())));
const markets=()=>`<div class="actions">${[['all','All markets'],...Object.entries(labels)].map(([v,n])=>`<button class="btn ${S.market===v?'primary':''}" data-action="market" data-value="${v}">${n}</button>`).join('')}</div>`;
function head(title,sub,actions=''){return `<div class="page-head"><div><div class="eyebrow">Your career, intentionally.</div><h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`}
function row(j){return `<tr><td><button class="table-role" data-action="job" data-id="${j.id}"><strong>${esc(j.title)}</strong><small>${esc(j.company)}</small></button></td><td>${esc(labels[j.market])}</td><td>${badge(j.stage)}</td><td>${esc(j.follow_up||'—')}</td><td>${button(icon('arrow'),'job',false,`data-id="${j.id}"`)}</td></tr>`}
function table(jobs){return jobs.length?`<div class="table-wrap"><table><thead><tr><th>Opportunity</th><th>Market</th><th>Stage</th><th>Follow-up</th><th></th></tr></thead><tbody>${jobs.map(row).join('')}</tbody></table></div>`:'<div class="empty-state"><h3>A fresh start.</h3><p>Search by role, save an opportunity and build your application kit.</p></div>'}
function firstApplication(){if(S.profile&&S.jobs.length&&S.resumes.some(r=>r.has_pdf))return '';return `<section class="panel onboarding"><div class="panel-head"><h2>Your first application, one clear step at a time.</h2></div><div class="setup-steps">${[['01','Start with your resume',S.profile?'Profile version saved. Review or add imported excerpts.':'Import a local PDF/DOCX/TXT resume, choose accurate excerpts, and save your profile.','profile','Review profile'],['02','Save the right opportunity',S.jobs.length?'Your saved jobs are ready to review.':'Search a role/location, read the description and choose your market.','discover','Find opportunities'],['03','Prepare, fill and track',S.resumes.some(r=>r.has_pdf)?'Frozen PDF ready. Upload and submit yourself, then record what happened.':'Open a saved job, build a reviewed PDF, then use the browser helper if useful.','applications','Open applications']].map(([n,title,text,action,label])=>`<article class="setup-step"><span class="setup-number">${n}</span><h3>${title}</h3><p>${text}</p>${button(label,action)}</article>`).join('')}</div></section>`}
function dashboard(){const due=S.jobs.filter(j=>j.follow_up&&j.follow_up<=localDate()&&!['closed','withdrawn'].includes(j.stage));return head('Make your next move.', 'A considered application starts with a clear workspace.',button(`${icon('search')} Find your next role`,'discover',true))+`<section class="hero"><div class="hero-content"><div class="eyebrow">Less friction. More direction.</div><h2>Your next chapter<br>starts with a good match.</h2><p>Discover opportunities, shape an honest resume and take your application into the browser.</p><div class="actions">${button('Explore opportunities '+icon('arrow'),'discover',true)}${button('Set up browser filling','helper')}</div></div><div class="hero-art" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="orbit orbit-three"></div><span>rw</span></div></section>${firstApplication()}<div class="metrics">${[['Saved opportunities',S.stats.saved,'briefcase'],['Active applications',S.stats.active,'arrow'],['In conversation',S.stats.interviews,'user'],['Follow-ups due',S.stats.due,'calendar']].map(([n,v,i])=>`<div class="metric"><div class="metric-top">${n}<span class="metric-icon">${icon(i)}</span></div><div class="metric-value">${v}</div><small class="muted">Your saved workspace</small></div>`).join('')}</div><div class="dashboard-grid"><section class="panel"><div class="panel-head"><h2>Application journey</h2>${button('View all','applications')}</div><div class="pipeline">${['saved','shortlisted','applied','interview','offer'].map((st,i)=>`<div class="pipeline-item"><span class="pipeline-number">0${i+1}</span><strong>${S.jobs.filter(j=>j.stage===st).length}</strong><small>${st}</small></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><h2>On your radar</h2>${icon('calendar')}</div>${due.length?due.slice(0,3).map(j=>`<div class="agenda-item"><span class="agenda-dot"></span><div><strong>${esc(j.company)}</strong><small>${esc(j.title)} · ${esc(j.follow_up)}</small></div>${button(icon('arrow'),'job',false,`data-id="${j.id}"`)}</div>`).join(''):'<div class="empty-state"><p>No overdue follow-ups. A little breathing room.</p></div>'}</section></div><section class="panel"><div class="panel-head"><h2>Your opportunities</h2>${button('+ Add posting','add')}</div>${table(S.jobs.slice(0,6))}</section>`}
function discover(){return head('Find work that fits.', 'Search a role and location. No company board URL required.')+`<form id="search-form" class="search-bar"><label class="field">Role or skill<input name="query" placeholder="Data engineer, Python, applied AI…" minlength="2" maxlength="160" required value="${esc(S.query||'')}"></label><label class="field">Location<input name="location" placeholder="Bengaluru, London…" maxlength="100" value="${esc(S.location||'')}"></label><label class="field">Country<select name="country"><option value="">Anywhere</option><option value="IN" ${S.country==='IN'?'selected':''}>India</option><option value="GB" ${S.country==='GB'?'selected':''}>United Kingdom</option><option value="US" ${S.country==='US'?'selected':''}>United States</option><option value="DE" ${S.country==='DE'?'selected':''}>Germany</option></select></label><label class="fact-choice"><input type="checkbox" name="remote" ${S.remote?'checked':''}>Remote</label><button class="btn primary" type="submit">${icon('search')} Search jobs</button></form><p class="footnote">${S.demo?'Synthetic preview: no provider is contacted.':'Explicit search sends only your query and filters to FreeHire. Personal/non-commercial API; source coverage and sponsorship are not guaranteed.'}</p><p id="search-status" role="status" aria-live="polite"></p><div class="actions"><span class="muted">Save to</span><select id="search-market"><option value="india_remote" ${S.saveMarket!=='relocation'?'selected':''}>India / remote</option><option value="relocation" ${S.saveMarket==='relocation'?'selected':''}>Relocation</option></select></div><div class="result-heading"><h2>${S.results?S.results.jobs.length+' opportunities · page '+(S.results.page.offset/20+1):'A better starting point'}</h2><span class="muted">${S.results?esc(S.results.source):'Your search, your direction'}</span></div>${S.results?`<p class="footnote">${esc(S.results.notice)} ${S.results.excluded.length} unsupported records excluded.</p><div class="actions pagination"><span class="muted">${esc(S.searchScope.query)} · ${esc(S.searchScope.country||'Anywhere')} · offset ${S.results.page.offset}</span>${button('Previous page','search-page',false,`data-offset="${S.results.page.offset-20}" ${S.results.page.offset===0?'disabled':''}`)}${button('Next page','search-page',false,`data-offset="${S.results.page.offset+20}" ${S.results.page.has_next?'':'disabled'}`)}</div><p class="footnote">Pages are separate observations. Listings may move or repeat as the source changes; absence is not closure. Search again to apply edited filters.</p><div class="job-grid">${S.results.jobs.map(j=>`<article class="job-card"><div class="company-mark">${esc(j.company.slice(0,2).toUpperCase())}</div><small class="muted">${esc(j.company)}</small><h3>${esc(j.title)}</h3><p>${icon('pin')} ${esc(j.location)}</p><p class="job-excerpt">${esc(j.posting.slice(0,210))}…</p><div class="actions">${button('Review & save','save-search',true,`data-id="${esc(j.id)}"`)}${safeLink(j.url,'Employer page')}</div></article>`).join('')}</div>`:'<section class="empty-state"><div class="empty-icon">'+icon('search')+'</div><h2>Your next opportunity is out there.</h2><p>Start with a role or skill. Review each description before saving.</p></section>'}`}
function applications(){return head('Every opportunity. In view.', 'Keep your two markets separate and your next step clear.',button('+ Add posting','add',true))+markets()+`<form id="board-filter-form" class="search-bar"><label class="field">Search your applications<input name="query" maxlength="500" placeholder="Role, company, note or source…" value="${esc(S.boardQuery||'')}"></label><label class="field">Stage<select name="stage"><option value="">All stages</option>${['saved','shortlisted','applied','interview','offer','closed','withdrawn'].map(v=>`<option ${S.boardStage===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="fact-choice"><input type="checkbox" name="due" ${S.boardDue?'checked':''}>Due through today</label><button class="btn primary">Apply filters</button>${button('Clear filters','clear-board')}</form><p class="footnote">${activeJobs().length} matching / ${S.jobs.length} saved reviews. Dashboard totals remain global.</p><div class="board">${['saved','shortlisted','applied','interview','offer'].map(stage=>`<section class="board-column"><div class="column-head"><h3>${stage}</h3><span>${activeJobs().filter(j=>j.stage===stage).length}</span></div>${activeJobs().filter(j=>j.stage===stage).map(j=>`<button class="job-card" data-action="job" data-id="${j.id}"><small>${esc(j.company)}</small><h3>${esc(j.title)}</h3><p>${esc(labels[j.market])}</p><small>${esc(j.follow_up?'Follow-up '+j.follow_up:'No reminder')}</small></button>`).join('')||'<div class="column-empty">Room for your next move.</div>'}</section>`).join('')}</div>${activeJobs().some(j=>['closed','withdrawn'].includes(j.stage))?`<section class="panel">${table(activeJobs().filter(j=>['closed','withdrawn'].includes(j.stage)))}</section>`:''}`}
function profile(){const p=S.profile?.profile||{};return head('Your story. Grounded in facts.', 'Reuse your real experience without inventing qualifications.')+`<form id="profile-form"><div class="split"><section class="panel"><div class="panel-head"><h2>Career profile</h2><div class="actions">${badge(S.profile?'Saved version':'New profile')}${button('Import existing resume','import-resume')}</div></div><div class="field-grid">${[['name','Full name'],['headline','Professional headline'],['first_name','First name for form filling'],['last_name','Last name for form filling'],['email','Email'],['phone','Phone'],['location','Location'],['linkedin','LinkedIn HTTPS URL'],['website','Portfolio HTTPS URL'],['links','Other links']].map(([k,l])=>field(k,l,p[k])).join('')}${area('summary','Professional summary',p.summary)}</div><div class="form-footer">${consent('I reviewed this profile and its factual claims.')}<button class="btn primary">Save profile version</button></div></section><section class="panel"><div class="panel-head"><h2>Your evidence library</h2>${button('+ Add fact','fact')}</div><p class="footnote">Facts stay attached to their source. Only reviewed facts can be selected for a resume.</p>${(S.draftFacts||p.facts||[]).map((f,i)=>`<article class="fact-card"><div class="fact-top"><span class="fact-section">${esc(f.section)}</span>${badge(f.reviewed?'Reviewed':'Needs review')}</div><p>${esc(f.claim)}</p><small class="source">${esc(f.source)}</small>${button('Edit','fact',false,`data-index="${i}"`)}</article>`).join('')||'<div class="empty-state">Add a project, skill, education or experience you can substantiate.</div>'}</section></div></form>`}
function letterCards(catalog){return `<div class="job-grid">${catalog.items.map(l=>`<article class="job-card"><div class="file-tile">${icon('mail')}</div><small class="muted">Saved cover letter · ${esc(l.id.slice(0,8))}</small><h3>${esc(l.title)}</h3><p>${esc(l.company)}</p><div class="actions">${button('Read letter','read-letter',false,`data-id="${l.id}"`)}${button('Download TXT','download',false,`data-kind="letter" data-id="${l.id}"`)}</div></article>`).join('')}</div>${catalog.issues.length?`<p class="error" role="alert">${esc(catalog.issues.join(' '))}</p>`:''}` }
function documents(){return head('Ready when you are.', 'Frozen resumes and saved cover letters, ready to reopen.')+`<h2 class="section-title">Resumes</h2>`+`<div class="job-grid">${S.resumes.map(r=>`<article class="job-card"><div class="file-tile">${icon('file')}</div><h3>${esc(r.label)}</h3><p>${esc(r.created_at.slice(0,10))}</p><div class="actions">${r.has_pdf?button('Download PDF','download',true,`data-kind="resume" data-id="${r.id}"`):''}${button('TXT','download',false,`data-kind="resume" data-format="txt" data-id="${r.id}"`)}</div></article>`).join('')||'<div class="empty-state"><h2>A resume with a destination.</h2><p>Open a saved job and choose “Build resume” to create your first version.</p></div>'}</div>`+`<h2 class="section-title">Cover letters</h2>`+letterCards(S.letters)}
function job(){const j=S.job,last=j.history.at(-1),p=S.profile?.profile;return `<button class="btn ghost back-link" data-action="applications">← All opportunities</button>`+head(esc(j.title),esc(j.company)+' · '+esc(labels[j.market]),safeLink(j.source_url))+`<div class="split"><section><div class="panel"><div class="panel-head"><h2>Application workspace</h2>${badge(last?.stage||'saved')}</div><div class="tabs">${[['posting','Job & evidence'],['kit','Application kit'],['activity','Activity']].map(([t,n])=>button(n,'tab',S.tab===t,`data-value="${t}"`)).join('')}</div>${S.tab==='posting'?`<div class="posting">${esc(j.posting)}</div><div class="panel-head"><h3>Evidence against requirements</h3>${button('+ Link evidence','evidence')}</div>${j.review.requirements.map(r=>`<article class="fact-card"><span class="pill">${r.evidence.length?'Evidence selected':'Open question'}</span><p>${esc(r.quote)}</p>${r.evidence.map(f=>`<small class="source">${esc(f.claim)}<br>Source: ${esc(f.source)}</small>`).join('')}</article>`).join('')||'<p class="footnote">Select an exact requirement quote and connect reviewed facts. A match is your assertion, not a qualification guarantee.</p>'}`:S.tab==='kit'?`<div class="panel-head"><h3>01 · Resume</h3>${button('Build resume','resume',true)}</div>${j.resumes.map(r=>`<div class="file-card">${icon('file')}<div><strong>${esc(r.label)}</strong><small>Exact job version</small></div>${button(r.has_pdf?'PDF':'TXT','download',false,`data-kind="resume" data-format="${r.has_pdf?'pdf':'txt'}" data-id="${r.id}"`)}${button('Cover letter','letter',false,`data-id="${r.id}"`)}</div>`).join('')||'<p class="footnote">Choose reviewed facts from your profile. Preview before freezing the PDF.</p>'}${letterCards(j.letters)}<div class="panel-head"><h3>02 · Send only recipient documents</h3>${button('Export application ZIP','packet')}</div><p class="footnote">Choose a resume below. Private evidence notes and history never belong in a recipient ZIP.</p><div class="panel-head"><h3>03 · Fill the employer form</h3>${button('Browser helper','helper',true)}</div><p class="footnote">Review supported contact fields, fill them, then upload your PDF and complete screening questions yourself. Final submission stays with you.</p>`:`<div class="panel-head"><h3>Application history</h3>${button('Update stage','track')}</div><div class="timeline">${j.history.map(e=>`<article><strong>${esc(e.stage)}</strong><small>${esc(e.recorded_at)} · revision ${e.revision}</small><p>${esc(e.note)}</p><small>Follow-up: ${esc(e.follow_up||'none')}</small></article>`).join('')||'<p>No submission recorded.</p>'}</div>`}</div></section><aside class="app-sidebar"><section class="panel"><div class="panel-head"><h3>Your next steps</h3>${icon('arrow')}</div><ol class="step-list"><li>Review the job and eligibility</li><li>${p?'Profile saved':'Add your career profile'}</li><li>${j.resumes.length?'Resume ready':'Build an honest resume'}</li><li>Open employer form and review filling</li><li>Submit yourself, then record it</li></ol><div class="actions">${button('Build resume','resume',true)}${button('Record my submission','submission')}</div><p class="footnote">Opening a link or filling fields does not mean an application was submitted.</p></section><section class="panel"><h3>Follow-up</h3><p>${esc(last?.follow_up||'No reminder set')}</p>${button('Update stage / reminder','track')}</section></aside></div>`}
function helper(){const p=S.profile?.profile;return head('From prepared to applied.', 'A small browser companion. You stay in control.')+`<section class="helper-hero panel"><div class="eyebrow">Browser-assisted applications</div><h2>Your contact details.<br>One careful handoff.</h2><p>Fill supported name, email, phone, location and professional-link fields. Preview every value on the employer page before you fill.</p>${button('Download Chrome / Edge helper','helper-download',true)}</section><div class="setup-steps">${[['Install once','Download and extract the helper ZIP. In chrome://extensions or edge://extensions, enable Developer mode and choose Load unpacked → RoleWeave-helper. No store publication yet.'],['Prepare on this page','Review the contact sheet below. Click Prepare, then click the helper toolbar icon on this RoleWeave tab and choose Load contact sheet.'],['Review on the employer form','Open the actual application form. Click the helper, review the destination and proposed fields, explicitly consent, then fill checked fields. Upload documents and submit yourself.']].map(([n,t],i)=>`<article class="setup-step"><span class="setup-number">0${i+1}</span><h3>${n}</h3><p>${t}</p></article>`).join('')}</div><section class="panel"><div class="panel-head"><h2>Your contact sheet</h2>${button('Edit profile','profile')}</div>${p?`<div class="contact-preview">${[['Full name',p.name],['First name',p.first_name],['Last name',p.last_name],['Email',p.email],['Phone',p.phone],['Location',p.location],['LinkedIn',p.linkedin],['Website',p.website]].map(([k,v])=>`<div><small>${k}</small><strong>${esc(v||'Not provided — left blank')}</strong></div>`).join('')}</div><form id="contact-form">${consent('Prepare only these contact values for the helper. Filling an employer page transmits them to that site; no career facts, credentials or history are included.')}<button class="btn primary">Prepare contact sheet</button>${button('Clear prepared sheet','clear-sheet')}</form>`:'<p>Save your profile before preparing a contact sheet.</p>'}<p class="footnote">Session memory only. No automatic submit, Next clicks, file upload, password, legal/demographic answers or background form scanning. Custom widgets, iframes and unsupported fields remain manual. Clear the helper after use.</p>${S.demo?'<a class="btn" href="/form-fixture.html" target="_blank">Open synthetic practice form</a>':''}</section>`}
function settings(){return head('A workspace you own.', 'Your data stays in a local SQLite shelf. Backups and documents are unencrypted.')+`<section class="panel">${[['Workspace recovery bundle','This workspace: database, saved letters, recipient ZIPs, original import files and managed source responses. Unencrypted; external exports/other workspaces are excluded.',button('Download recovery ZIP','bundle',true)],['Restore recovery bundle','Preview and validate a trusted bundle, then create a separate workspace. The current one is preserved.','<label class="btn">Choose recovery ZIP<input id="recovery-file" type="file" accept=".zip" hidden></label>'],['Database-only backup','Profiles, reviews, resumes and tracking only. Saved web artifacts are not included.',button('Download database JSON','backup')],['Restore safely','Compatible records are merged; conflicting records are refused. Keep a backup first.','<label class="btn">Choose backup<input id="restore-file" type="file" accept=".json" hidden></label>'],['Advanced native tools','Existing provider boards, optional AI / Calendar setup, audits and rehearsal remain available in the native workspace.',button('Open advanced tools','legacy')],['Browser helper','Install the companion once, then review each form before filling.',button('Set up helper','helper')],['Close local host','Closing this browser tab leaves the local host running. Use this button to stop it.',button('Quit RoleWeave','quit')]].map(([n,t,a])=>`<div class="settings-row"><div><h3>${n}</h3><p>${t}</p></div>${a}</div>`).join('')}</section><section class="panel"><div class="panel-head"><h2>Recovered workspaces</h2></div>${S.recoveries.items.map(r=>`<div class="settings-row"><div><h3>Recovered bundle · ${esc(r.id.slice(0,8))}</h3><p>Independent workspace; opening it keeps this one running.</p></div>${button('Open recovered workspace','open-recovery',false,`data-id="${r.id}"`)}</div>`).join('')||'<p class="footnote">No completed recovered workspaces yet.</p>'}${S.recoveries.issues.map(i=>`<p class="error">${esc(i)}</p>`).join('')}</section>`}
function render(){const views={dashboard,discover,applications,profile,documents,helper,settings,job};$('#app').innerHTML=`<div class="app-shell"><aside class="rail"><a class="brand" href="#" data-action="dashboard">${mark}<span class="wordmark">RoleWeave</span></a><div class="rail-label">WORKSPACE</div><nav class="nav">${[['dashboard','grid','Overview'],['discover','search','Discover jobs'],['applications','briefcase','Applications'],['profile','user','Career profile'],['documents','file','Documents'],['helper','bolt','Browser helper']].map(([v,i,n])=>`<button data-action="${v}" class="${S.view===v?'active':''}">${icon(i)}<span class="nav-label">${n}</span></button>`).join('')}</nav><div class="rail-bottom"><nav class="nav"><button data-action="settings">${icon('settings')}<span class="nav-label">Settings & backup</span></button></nav><div class="local-status"><span class="status-dot"></span>Local workspace · v${esc(S.version)}</div><div class="profile-mini"><div class="avatar">${esc((S.profile?.profile.name||'You').slice(0,2).toUpperCase())}</div><div><strong>${esc(S.profile?.profile.name||'Your workspace')}</strong><small>${S.demo?'Synthetic practice':'Built around you'}</small></div></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">${esc(S.workspace_label||'Workspace')} <span>/</span> ${esc(S.view)}</div><div class="top-actions">${S.demo?'<span class="pill demo-pill">SYNTHETIC PREVIEW</span>':''}<span class="local-pill">${icon('shield')} Private by default</span></div></header>${views[S.view]()}</main></div>`}
async function navigate(view){if(S.dirty&&!confirm('Discard unsaved profile edits?'))return;S.dirty=false;S.draftFacts=null;S.view=view;render();window.scrollTo(0,0)}
function keepImportedFacts(facts){const draft=formData($('#profile-form'));const current=S.draftFacts||structuredClone(S.profile?.profile.facts||[]);const ids=new Set(current.map(f=>f.id));S.draftFacts=[...current,...facts.filter(f=>!ids.has(f.id))];S.modalDirty=false;close();render();for(const [k,v]of Object.entries(draft)){const field=$('#profile-form').elements.namedItem(k);if(field&&field.type!=='checkbox')field.value=v}S.dirty=true;toast('Excerpts added to your profile draft. Review and save the profile.')}
function showResumePreview(preview){S.resumePreview=preview;$('#resume-import-result').innerHTML=`<p class="footnote">${esc(preview.name)} · ${preview.blocks.length} text blocks. PDF text order/line breaks can differ from the document. Choose only accurate excerpts; edit facts afterward if needed.</p><details><summary>Read extracted text</summary><pre class="document-preview">${esc(preview.text)}</pre></details><form id="resume-import-form"><div class="import-blocks">${preview.blocks.map(b=>`<div class="import-block"><label class="fact-choice"><input name="block" type="checkbox" value="${b.id}"><span>${esc(b.text)}</span></label><label class="field">Section<select name="section-${b.id}"><option value="">Choose a section</option>${['Experience','Projects','Education','Skills','Additional'].map(v=>`<option>${v}</option>`).join('')}</select></label></div>`).join('')}</div>${consent('I reviewed the selected excerpts and their sections. They are my assertions, not verified employment claims.')}<button class="btn primary">Add selected excerpts to draft</button></form>`}
async function packetLetters(){const f=$('#packet-form'),resume=await api('resume?id='+f.elements.resume_id.value),select=f.elements.letter_id;select.innerHTML='<option value="">No cover letter</option>'+S.job.letters.items.filter(l=>l.profile_id===resume.profile_id&&l.profile_sha256===resume.profile_sha256).map(l=>`<option value="${l.id}">${esc(l.title)} · ${esc(l.id.slice(0,8))}</option>`).join('');f.elements.confirmed.checked=false}
async function runSearch(scope){if(S.searchBusy)throw Error('Wait for the current search to finish.');S.searchBusy=true;const status=$('#search-status');if(status){status.textContent='Searching jobs…';status.className='footnote'}const controls=[...document.querySelectorAll('#search-form button,[data-action=search-page]')].map(el=>[el,el.disabled]);for(const [el]of controls)el.disabled=true;const previous=S.results;try{const result=await api('search',scope);S.results=result;S.searchScope={...scope};S.query=scope.query;S.location=scope.location;S.country=scope.country;S.remote=scope.remote;render()}catch(e){S.results=previous;const status=$('#search-status');if(status){status.textContent=e.message;status.className='error'}throw e}finally{S.searchBusy=false;for(const [el,disabled]of controls)if(el.isConnected)el.disabled=disabled}}
async function openJob(id){S.job=await api('job?id='+encodeURIComponent(id));S.view='job';S.tab='posting';S.letter=null;render()}
function choices(facts){return facts.filter(f=>f.reviewed).map(f=>`<label class="fact-choice"><input type="checkbox" name="fact_ids" value="${esc(f.id)}"><span>${esc(f.claim)}<small class="source">${esc(f.source)}</small></span></label>`).join('')||'<p class="footnote">Add reviewed facts to your profile first.</p>'}
function resumeStudio(){return `<form id="resume-form"><div class="studio-grid"><section class="studio-controls"><div class="eyebrow">01 / Shape your resume</div>${field('label','Private version label',S.job.title+' resume')}<fieldset class="layout-picker"><legend>Document layout</legend>${[['classic','Classic','Quiet and familiar'],['slate','Slate','Clean teal accents'],['editorial','Editorial','Bold violet headings']].map(([v,n,t])=>`<label class="layout-tile"><input name="theme" type="radio" value="${v}" ${v==='classic'?'checked':''}><span class="layout-sample ${v}" aria-hidden="true"><i></i><i></i><i></i></span><strong>${n}</strong><small>${t}</small></label>`).join('')}</fieldset><div class="panel-head"><h3>Choose your evidence</h3></div><p class="footnote">Only selected reviewed facts are printed. Move facts within a section to lead with your best example. Section order stays fixed.</p>${['Experience','Projects','Education','Skills','Additional'].map(section=>{const facts=S.profile.profile.facts.filter(f=>f.reviewed&&f.section===section);return facts.length?`<fieldset class="studio-section"><legend>${section}</legend>${facts.map(f=>`<div class="studio-fact"><label class="fact-choice"><input name="fact_ids" type="checkbox" value="${esc(f.id)}"><span>${esc(f.claim)}<small class="source">${esc(f.source)}</small></span></label><div class="fact-order">${button('↑','move-fact',false,'data-direction="up" aria-label="Move fact up"')}${button('↓','move-fact',false,'data-direction="down" aria-label="Move fact down"')}</div></div>`).join('')}</fieldset>`:''}).join('')}<p class="footnote">Edit factual wording in Career profile. This studio changes selection, order and layout; it never invents qualifications.</p></section><section class="studio-preview"><div class="eyebrow">02 / Review your document</div><p id="preview-state" class="footnote" role="status">Choose facts and a layout, then preview. Nothing is saved yet.</p><div id="resume-layout-preview" role="document" aria-label="Resume layout preview" hidden></div><details><summary>Read exact document text</summary><pre id="document-preview" class="document-preview" hidden></pre></details></section></div><div class="studio-footer"><button class="btn" name="preview" formnovalidate>Preview resume</button><div id="freeze-controls" hidden>${consent('I reviewed the current layout, identity and selected facts.')}<button class="btn" type="button" data-action="preview-pdf">Download preview PDF</button><button class="btn primary" name="freeze">Save & download PDF</button></div></div></form>`}
function documentBinding(form){const d=formData(form);return form.id==='resume-form'?{...profileBinding(),job_id:S.job.id,fact_ids:selected(form),label:d.label,theme:d.theme}:{job_id:S.job.id,resume_id:form.dataset.resume,fact_ids:selected(form),motivation:d.motivation,closing:d.closing,include_pdf:true}}
function showResumeLayout(html,theme){const main=new DOMParser().parseFromString(html,'text/html').querySelector('main');if(!main)throw Error('Resume layout preview is unavailable.');const host=$('#resume-layout-preview'),root=host.shadowRoot||host.attachShadow({mode:'open'}),css=document.createElement('link'),paper=document.createElement('article');css.rel='stylesheet';css.href='/document-preview.css';paper.className='paper '+theme;paper.append(main);root.replaceChildren(css,paper)}
function invalidateDocument(){S.documentPreview=null;const c=$('#freeze-controls');if(c){c.hidden=true;c.querySelector('[name=confirmed]').checked=false}const frame=$('#resume-layout-preview');if(frame){frame.hidden=true;frame.shadowRoot?.replaceChildren();$('#preview-state').textContent='Selection or layout changed. Preview again before saving.'}}
function selected(form){return [...form.querySelectorAll('[name=fact_ids]:checked')].map(i=>i.value)}
function revision(){return S.job.history.at(-1)?.revision||0}
function localDate(){const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}
function formData(f){return Object.fromEntries(new FormData(f))}
function profileBinding(){if(!S.profile)throw Error('Save your career profile first.');return {profile_id:S.profile.id,profile_sha256:S.profile.snapshot_sha256}}
document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el)return;event.preventDefault();const a=el.dataset.action;try{
 if(['dashboard','discover','applications','profile','documents','helper','settings'].includes(a))return await navigate(a);
 if(a==='close')return close();if(a==='job')return await openJob(el.dataset.id);
 if(a==='clear-board'){S.boardQuery='';S.boardStage='';S.boardDue=false;S.market='all';render()}if(a==='market'){S.market=el.dataset.value;render()}if(a==='tab'){S.tab=el.dataset.value;render()}
 if(a==='add')modal('Save an opportunity',`<form id="job-form"><div class="field-grid">${field('title','Job title')}${field('company','Company')}${field('source_url','Employer HTTPS link (optional)')}<label class="field">Market<select name="market"><option value="india_remote">India / remote</option><option value="relocation">Relocation</option></select></label>${area('posting','Job description','',50000)}</div><button class="btn primary">Save opportunity</button></form>`);
 if(a==='search-page')await runSearch({...S.searchScope,offset:Number(el.dataset.offset)});
 if(a==='save-search'){const j=await api('search/save',{search_id:S.results.search_id,job_id:el.dataset.id,market:$('#search-market').value});await refresh();await openJob(j.id);toast('Opportunity saved. Review the job before applying.')}
 if(a==='import-resume')modal('Start with your existing resume',`<p class="footnote">Choose a text PDF, DOCX or UTF-8 TXT file (up to4MiB). Extraction stays on this computer. Scanned PDFs need an external OCR/text copy. Nothing becomes a reviewed fact until you choose and confirm it.</p><label class="btn">Choose resume<input id="resume-file" type="file" accept=".pdf,.docx,.txt" hidden></label><p id="resume-import-status" role="status"></p><div id="resume-import-result"></div>`);
 if(a==='fact'){const facts=S.draftFacts||structuredClone(S.profile?.profile.facts||[]),i=el.dataset.index,f=i===undefined?{}:facts[+i];modal('Career fact',`<form id="fact-form" data-index="${i??''}"><label class="field">Section<select name="section">${['Experience','Projects','Education','Skills','Additional'].map(s=>`<option ${s===f.section?'selected':''}>${s}</option>`).join('')}</select></label>${area('claim','Factual claim',f.claim)}${area('source','Source / evidence',f.source)}<label class="fact-choice"><input name="reviewed" type="checkbox" ${f.reviewed?'checked':''}>I reviewed this claim and its source.</label><button class="btn primary">Keep in profile draft</button></form>`)}
 if(a==='resume'){profileBinding();modal('Build your application resume',resumeStudio())}
 if(a==='move-fact'){const row=el.closest('.studio-fact'),other=el.dataset.direction==='up'?row.previousElementSibling:row.nextElementSibling;if(other?.classList.contains('studio-fact')){if(el.dataset.direction==='up')other.before(row);else other.after(row);S.modalDirty=true;invalidateDocument()}}
 if(a==='preview-pdf'){if(!S.documentPreview)throw Error('Preview the current document first.');const bytes=Uint8Array.from(atob(S.documentPreview.pdf_base64),c=>c.charCodeAt(0)),url=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'})),link=document.createElement('a');link.href=url;link.download='review-preview.pdf';link.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}
 if(a==='evidence'){profileBinding();modal('Connect evidence to a requirement',`<form id="evidence-form">${area('quote','Paste an exact requirement quote from this job')}${choices(S.profile.profile.facts)}${consent('I reviewed this exact quote and the selected evidence.')}<p class="footnote">No selected facts leaves an explicit evidence gap. This creates a new review; earlier tracking stays attached to the old review.</p><button class="btn primary">Save reviewed connection</button></form>`)}
 if(a==='letter'){const frozen=await api('resume?id='+el.dataset.id);modal('Write your cover letter',`<form id="letter-form" data-resume="${el.dataset.id}">${area('motivation','Your introduction — why this role?')}${area('closing','Your closing','Thank you for considering my application.')}${choices(frozen.profile.facts)}<button class="btn" name="preview" formnovalidate>Preview letter</button><pre id="document-preview" class="document-preview" hidden></pre><div id="freeze-controls" hidden>${consent('I reviewed this letter and its factual claims.')}<button class="btn" type="button" data-action="preview-pdf">Download preview PDF</button><button class="btn primary" name="freeze">Save & download PDF</button></div></form>`)}
 if(a==='read-letter'){const l=await api('letter?id='+el.dataset.id);modal('Saved cover letter',`<pre class="document-preview">${esc(l.text)}</pre>${l.has_pdf?button('Download PDF','download',true,`data-kind="letter" data-format="pdf" data-id="${el.dataset.id}"`):''}${button('Download TXT','download',false,`data-kind="letter" data-format="txt" data-id="${el.dataset.id}"`)}`)}
 if(a==='packet'){if(!S.job.resumes.some(r=>r.has_pdf))throw Error('Create a PDF resume for this job first.');modal('Export recipient documents',`<form id="packet-form"><label class="field">Frozen resume<select name="resume_id">${S.job.resumes.filter(r=>r.has_pdf).map(r=>`<option value="${r.id}">${esc(r.label)}</option>`).join('')}</select></label><label class="field">Optional matching cover letter<select name="letter_id"><option value="">No cover letter</option></select></label><p class="footnote">Resume PDF and the matching letter PDF when available (TXT for older letters). Private sources and history stay out.</p>${consent('Export these selected recipient documents.')}<button class="btn primary">Download ZIP</button></form>`);await packetLetters()}
 if(a==='track'){const last=S.job.history.at(-1);modal('Update application stage',`<form id="track-form"><label class="field">Stage<select name="stage">${['saved','shortlisted','applied','interview','offer','closed','withdrawn'].map(s=>`<option ${(S.job.history.at(-1)?.stage||'saved')===s?'selected':''}>${s}</option>`).join('')}</select></label>${area('note','Your note')}${field('follow_up','Follow-up date',last?.follow_up||'','date')}<p class="footnote">Your existing reminder is kept unless you change or clear it.</p><p id="tracking-current" class="footnote">Current revision ${revision()} · ${esc(last?.stage||'saved')}</p>${button('Reload current tracking','reload-tracking')}<button class="btn primary">Save update</button></form>`)}
 if(a==='submission')modal('Record your completed submission',`<form id="submission-form">${field('submitted_on','Actual submission date',localDate(),'date')}<label class="field">Channel<select name="channel"><option>Employer portal</option><option>Email</option><option>Referral</option><option>Other</option></select></label>${field('reference','Receipt / confirmation reference (optional)')}${area('note','Private note')}${field('follow_up','Follow-up date',S.job.history.at(-1)?.follow_up||'','date')}<p id="tracking-current" class="footnote">Current revision ${revision()} · ${esc(S.job.history.at(-1)?.stage||'saved')}</p>${button('Reload current tracking','reload-tracking')}${consent('I submitted this application myself. This record is my observation.')}<button class="btn primary">Record submission</button></form>`);
 if(a==='reload-tracking'){const fresh=await api('job?id='+S.job.id);S.job=fresh;const label=$('#tracking-current');label.textContent=`Current revision ${revision()} · ${fresh.history.at(-1)?.stage||'saved'} · latest reminder ${fresh.history.at(-1)?.follow_up||'none'} · latest note: ${fresh.history.at(-1)?.note||'none'}. Your draft is preserved: review it against this latest state before saving.`;const checkbox=$('#submission-form [name=confirmed]');if(checkbox)checkbox.checked=false;toast('Latest tracking loaded. Review your preserved draft before saving.')}
 if(a==='download')await download('download?kind='+el.dataset.kind+'&id='+el.dataset.id+'&format='+(el.dataset.format||'pdf'));
 if(a==='helper-download')await download('browser-helper');if(a==='clear-sheet'){$('#roleweave-fill-profile')?.remove();toast('Prepared sheet cleared. Clear the helper separately.')}
 if(a==='bundle')await download('workspace-bundle');if(a==='open-recovery'){await api('recovery/open',{id:el.dataset.id,confirmed:true});toast('Recovered workspace opened in a separate browser tab.')}
 if(a==='backup')await download('backup');if(a==='legacy')await api('legacy',{confirmed:true});if(a==='quit'&&confirm('Stop the local RoleWeave host?')){await api('quit',{confirmed:true});$('#app').innerHTML='<main class="main"><h1>Workspace closed.</h1><p>You can close this tab.</p></main>'}
 }catch(error){toast(error.message)}});
document.addEventListener('submit',async event=>{const f=event.target;if(!f.id)return;event.preventDefault();const d=formData(f),submitter=event.submitter;submitter?.setAttribute('disabled','');try{
 if(f.id==='recovery-form'){const result=await api('recovery/restore',{id:S.recoveryPreview.id,sha256:S.recoveryPreview.summary.sha256,confirmed:!!d.confirmed});S.modalDirty=false;close();await refresh();render();modal('Recovered workspace is ready',`<p>Your current workspace was preserved. Open the recovered copy to inspect its profiles, documents and jobs.</p>${button('Open recovered workspace','open-recovery',true,`data-id="${result.id}"`)}`)}
 if(f.id==='board-filter-form'){S.boardQuery=d.query.trim();S.boardStage=d.stage;S.boardDue=!!d.due;render()}
 if(f.id==='search-form')await runSearch({query:d.query,location:d.location,country:d.country,remote:!!d.remote,offset:0});
 if(f.id==='job-form'){const j=await api('jobs',d);S.modalDirty=false;close();await refresh();await openJob(j.id)}
 if(f.id==='profile-form'){const fields=['name','headline','email','phone','location','links','summary','first_name','last_name','linkedin','website'],p=Object.fromEntries(fields.map(k=>[k,d[k]||'']));p.facts=S.draftFacts||S.profile?.profile.facts||[];await api('profile',{profile:p,confirmed:!!d.confirmed});S.dirty=false;S.draftFacts=null;await refresh();render();toast('Profile version saved.')}
 if(f.id==='resume-import-form'){const selected=[...f.querySelectorAll('[name=block]:checked')].map(el=>({id:el.value,section:f.elements.namedItem('section-'+el.value).value}));const result=await api('resume-import/commit',{id:S.resumePreview.id,selected,confirmed:!!d.confirmed});keepImportedFacts(result.facts)}
 if(f.id==='fact-form'){const facts=S.draftFacts||structuredClone(S.profile?.profile.facts||[]),i=f.dataset.index,v={id:i===''?crypto.randomUUID():facts[+i].id,section:d.section,claim:d.claim,source:d.source,reviewed:!!d.reviewed};if(i==='')facts.push(v);else facts[+i]=v;const draft=formData($('#profile-form'));S.draftFacts=facts;S.modalDirty=false;close();render();for(const [k,v]of Object.entries(draft)){const e=$('#profile-form').elements.namedItem(k);if(e&&e.type!=='checkbox')e.value=v}S.dirty=true;toast('Fact kept in draft. Review and save your profile.')}
 if(f.id==='resume-form'||f.id==='letter-form'){const binding=documentBinding(f),signature=JSON.stringify(binding),freezing=submitter.name==='freeze';if(freezing&&(!S.documentPreview||S.documentPreview.signature!==signature))throw Error('The document changed. Preview and review it again.');const data={...binding,confirmed:!!d.confirmed,...(freezing?{preview_sha256:S.documentPreview.preview_sha256}:{})},kind=f.id==='resume-form'?'resume':'letter';const r=await api(kind+(freezing?'':'/preview'),data);if(!f.isConnected)return;if(freezing){S.modalDirty=false;close();await refresh();S.job=await api('job?id='+S.job.id);S.tab='kit';render();await download('download?kind='+kind+'&id='+r.id+'&format=pdf')}else{if(signature!==JSON.stringify(documentBinding(f)))return;S.documentPreview={...r,signature};const frame=$('#resume-layout-preview');if(frame){showResumeLayout(r.html,binding.theme);frame.hidden=false;$('#preview-state').textContent='Current HTML layout. Download the preview PDF to check its exact pagination.'}$('#document-preview').textContent=r.text;$('#document-preview').hidden=false;$('#freeze-controls').hidden=false}}
 if(f.id==='evidence-form'){const j=await api('review/from-profile',{...profileBinding(),job_id:S.job.id,quote:d.quote,fact_ids:selected(f),confirmed:!!d.confirmed});S.modalDirty=false;close();await refresh();await openJob(j.id)}
 if(f.id==='packet-form'){const r=await api('packet',{job_id:S.job.id,resume_id:d.resume_id,letter_id:d.letter_id||undefined,formats:d.letter_id?['pdf',S.job.letters.items.find(l=>l.id===d.letter_id)?.has_pdf?'letter-pdf':'letter']:['pdf'],confirmed:!!d.confirmed});S.modalDirty=false;close();await download('download?kind=packet&id='+r.id)}
 if(f.id==='track-form'||f.id==='submission-form'){await api(f.id==='track-form'?'track':'submission',{...d,...(f.id==='submission-form'?{confirmed:!!d.confirmed}:{}),job_id:S.job.id,expected_revision:revision()});S.modalDirty=false;close();await refresh();S.job=await api('job?id='+S.job.id);S.tab='activity';render();toast('Application history saved.')}
 if(f.id==='contact-form'){const r=await api('autofill-profile');$('#roleweave-fill-profile')?.remove();const e=document.createElement('script');e.id='roleweave-fill-profile';e.type='application/json';e.textContent=JSON.stringify(r);document.body.append(e);toast('Contact sheet prepared. Open the helper on this tab to load it.')}
 }catch(error){const target=$('#modal[open] .modal-error');if(target)target.textContent=error.message;else toast(error.message)}finally{submitter?.removeAttribute('disabled')}});
document.addEventListener('input',event=>{if(event.target.closest('#profile-form'))S.dirty=true;if(event.target.closest('#modal'))S.modalDirty=true;if(event.target.closest('#resume-form,#letter-form')&&event.target.name!=='confirmed')invalidateDocument()});
$('#modal').addEventListener('cancel',e=>{e.preventDefault();close()});
document.addEventListener('change',async event=>{if(event.target.id==='resume-file'){const requestId=crypto.randomUUID();S.importRequest=requestId;event.target.disabled=true;const file=event.target.files[0];if(!file){event.target.disabled=false;return}const status=$('#resume-import-status');try{if(file.size>4*1024*1024)throw Error('Resume exceeds4MiB. Choose a smaller copy.');status.textContent='Extracting locally…';const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=32768)binary+=String.fromCharCode(...bytes.subarray(i,i+32768));const preview=await api('resume-import/preview',{name:file.name,base64:btoa(binary)});if(S.importRequest===requestId&&event.target.isConnected){showResumePreview(preview);status.textContent='Preview ready. Your profile has not changed.'}}catch(e){status.textContent=e.message}finally{event.target.disabled=false}return}if(event.target.id==='recovery-file'){const requestId=crypto.randomUUID();S.recoveryRequest=requestId;const file=event.target.files[0];if(!file)return;try{if(file.size>64*1024*1024)throw Error('Workspace ZIP exceeds64MiB.');modal('Checking recovery bundle',`<p>Validating the archive, fingerprints and database. The current workspace has not changed.</p>`);const response=await fetch('/api/recovery/preview',{method:'POST',headers:{'Content-Type':'application/octet-stream','X-RoleWeave-Token':$('meta[name=roleweave-session]').content},body:file});const result=await response.json();if(S.recoveryRequest!==requestId||!$('#modal').open||!$('#modal-content h2')?.textContent.includes('Checking recovery bundle'))return;if(!response.ok)throw Error(result.error);S.recoveryPreview=result;const m=result.summary;$('#modal-content').innerHTML=`<div class="modal-head"><h2>Review workspace recovery</h2>${button('×','close')}</div><div class="modal-body"><p>${m.jobs} jobs · ${m.profiles} profiles · ${m.resumes} resumes · ${m.files-1} managed files</p><p class="footnote">${Object.entries(m.artifacts).map(([k,v])=>esc(k)+': '+v).join(' · ')}</p><p class="footnote">Restore your own trusted backup. Hash checks verify consistency, not authorship or the truth of reviewed claims. A new independent workspace will be created; this one stays unchanged.</p><form id="recovery-form">${consent('Create this recovered workspace from the reviewed bundle.')}<button class="btn primary">Create recovered workspace</button></form><p class="modal-error" role="alert"></p></div>`}catch(e){const message=$('#modal[open] .modal-error');if(message)message.textContent=e.message;else toast(e.message)}return}if(event.target.id==='search-market'){S.saveMarket=event.target.value;return}if(event.target.closest('#packet-form')){try{if(event.target.name==='resume_id')await packetLetters();const c=$('#packet-form [name=confirmed]');if(event.target.name!=='confirmed')c.checked=false}catch(e){toast(e.message)}return}if(event.target.id!=='restore-file')return;const file=event.target.files[0];if(!file||!confirm('Merge this backup into your workspace? Keep a current backup first.'))return;try{const r=await fetch('/api/restore',{method:'POST',headers:{'X-RoleWeave-Token':$('meta[name=roleweave-session]').content,'Content-Type':'application/octet-stream'},body:file}),d=await r.json();if(!r.ok)throw Error(d.error);await refresh();render();toast(`Restored ${d.added}; skipped ${d.skipped}.`)}catch(e){toast(e.message)}});
window.addEventListener('beforeunload',e=>{if(S.dirty||S.modalDirty){e.preventDefault();e.returnValue=''}});
refresh().then(render).catch(e=>{$('#app').innerHTML=`<main class="main"><h1>Could not open workspace</h1><p>${esc(e.message)}</p></main>`});
